dtsPropsFor.SurahListItem:
surah: { number: number; nameArabic: string; nameEnglish: string; ayahCount: number; revelationType: 'Makki' | 'Madani'; revelationOrder: number; juzStart: number };
onSelect: (surahNumber: number) => void;
onOpen: (surahNumber: number) => void;
isActive?: boolean;

dtsPropsFor.JuzListItem:
juz: { number: number; startSurah: number; startAyah: number; endSurah: number; endAyah: number };
/** Surah number to display name, used for the range label. */
surahNames: Map<number, string>;
onSelect: (juzNumber: number) => void;
onOpen: (juzNumber: number) => void;
isActive?: boolean;

dtsPropsFor.InfoSheet:
visible: boolean;
title: string;
/** `numeric` opts a value out of the Arabic UI font, whose digits sit inside ayah-marker ornaments. */
rows: Array<{ label: string; value: string; numeric?: boolean }>;
note?: string;
onClose: () => void;

dtsPropsFor.BookmarkSavedSnackbar:
surahName: string;
pageNumber: number;
juzNumber: number;
resultingCategories: Array<'reading' | 'recitation'>;
/** Confirms a completed Undo: restates the restored state and drops the Undo action. */
undone?: boolean;
onUndo: () => void;
onDismiss: () => void;

dtsPropsFor.BookmarkCategorySheet:
surahName: string;
ayahNumber: number;
initialCategories: Array<'reading' | 'recitation'>;
onCommit: (categories: Array<'reading' | 'recitation'>) => void;
onDismiss: () => void;

dtsPropsFor.PrayerBand:
day: {
  times: Record<'fajr' | 'dhuhr' | 'asr' | 'maghrib' | 'isha', Date>;
  /** The prayer whose time has most recently passed, or null before Fajr. */
  current: 'fajr' | 'dhuhr' | 'asr' | 'maghrib' | 'isha' | null;
  next: { name: 'fajr' | 'dhuhr' | 'asr' | 'maghrib' | 'isha'; at: Date };
};
city: string;
now: Date;

dtsPropsFor.QiblahWidget:
point: { latitude: number; longitude: number };
size?: number;
style?: object;

dtsPropsFor.AyahPopup:
selection: { startSurah: number; startAyah: number; endSurah: number; endAyah: number };
/** Screen position of the tapped ayah, in pixels. */
x: number;
y: number;
onAction: (
  action: 'play' | 'tafsir' | 'bookmark' | 'copy' | 'share' | 'wordByWord',
  selection: { startSurah: number; startAyah: number; endSurah: number; endAyah: number },
) => void;
onDismiss: () => void;

dtsPropsFor.AyahResultRow:
result: { surahNumber: number; ayahNumber: number; textUthmani: string; juzNumber: number; pageNumber: number };
surahNameArabic: string;
surahNameEnglish: string;
/** The search term, highlighted inside the ayah text. */
query: string;
onPress?: (result: { surahNumber: number; ayahNumber: number; textUthmani: string; juzNumber: number; pageNumber: number }) => void;
onPlay?: (result: { surahNumber: number; ayahNumber: number; textUthmani: string; juzNumber: number; pageNumber: number }) => void;
onCopy?: (result: { surahNumber: number; ayahNumber: number; textUthmani: string; juzNumber: number; pageNumber: number }) => void;
onBookmark?: (result: { surahNumber: number; ayahNumber: number; textUthmani: string; juzNumber: number; pageNumber: number }) => void;

dtsPropsFor.TabBar:
/** Supplied by expo-router's Tabs navigator; this bar is not meant to be built by hand. */
state: { index: number; routes: Array<{ key: string; name: string }> };
descriptors: Record<string, { options: { title?: string; tabBarLabel?: string } }>;
navigation: { navigate: (name: string) => void; emit: (event: object) => { defaultPrevented: boolean } };
insets: { top: number; right: number; bottom: number; left: number };

dtsPropsFor.ContinueReadingWidget:
/** 'resume' also requires surahNumber, surahName, ayahNumber, juzNumber and pageNumber. 'start' takes onPress alone. */
variant: 'resume' | 'start';
surahNumber?: number;
surahName?: string;
ayahNumber?: number;
juzNumber?: number;
pageNumber?: number;
onPress: () => void;
